(()=>{'use strict';
const $=id=>document.getElementById(id),canvas=$('scene'),ctx=canvas.getContext('2d'),M=NormalMath;
const state={step:0,mu:200,sigma:20,yaw:-.26,pitch:.18,zoom:1,area:'ninetyfive',playing:false,z:1,n:9};
const current={mu:200,sigma:20,yaw:state.yaw,pitch:state.pitch,zoom:1};
const colors={ink:'#204b3b',green:'#237e5c',gold:'#c2954c',blue:'#608ba5',grid:'#d4e1d4',muted:'#829582'};
const keywords=['钟形 · 连续','左右各半','μ − σ · μ + σ','面积 · 概率','反复抽样 · 每组一个均值','X 与 X̄ · 标准差与标准误','分别中心化 · 除各自标准差','阴影面积 · 累积高度','小矩形 · 积分'];
const descriptions=['正态分布：钟形曲线，两端趋近于零。','正态分布关于均值对称，均值左右两侧面积各为50%。','两个拐点位于均值减一个标准差和均值加一个标准差处。','曲线下总面积为1，中央95%区间约为均值加减1.96个标准差，两侧尾部各约2.5%。','从正态总体独立随机抽取n个观测值，求出一个样本均值；反复抽样形成样本均值的抽样分布。','单个观测X的标准差为σ，样本均值X̄的标准差即标准误为σ除以根号n；两者期望相同。','已知总体σ，X减μ后除以σ，X̄减μ后除以σ除以根号n，两者都服从标准正态分布。','标准正态累积分布Φ(z)=P(Z≤z)，等于密度从负无穷到z的面积。','每块小矩形面积等于密度乘以宽度；矩形和加上未显示的左尾逼近Φ(z)。'];
let w=0,h=0,dpr=1,scale=1,last=performance.now(),stepStart=last,autoStart=last,needDraw=true,baseDrag=null;
let extension=null,sampling=null;
const pointers=new Map(),clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),number=(x,n=1)=>Math.abs(x)<1e-9?'0':Number(x.toFixed(n)).toString();
function resize(){let box=canvas.getBoundingClientRect();w=box.width;h=box.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);scale=Math.min(w/13.6,h/6.1);needDraw=true}
new ResizeObserver(resize).observe(canvas);
function world(x,y,z=0){return[(x-200)/25,y,z]}
function project(p){const [x,y0,z]=p,y=(y0-1)*(w<600?1.9:1),cy=Math.cos(current.yaw),sy=Math.sin(current.yaw),cp=Math.cos(current.pitch),sp=Math.sin(current.pitch),xx=x*cy+z*sy,zz=-x*sy+z*cy,yy=y*cp-zz*sp,depth=y*sp+zz*cp,k=18/(18+depth);return{x:w*.5+xx*scale*current.zoom*k,y:h*.51-yy*scale*current.zoom*k}}
const height=x=>M.pdf(x,current.mu,current.sigma)*100;
function poly(points,{fill,stroke,width=1,dash=[],close=false,alpha=1}={}){if(points.length<2)return;ctx.save();ctx.globalAlpha=alpha;ctx.beginPath();points.forEach((p,i)=>{let s=project(p);i?ctx.lineTo(s.x,s.y):ctx.moveTo(s.x,s.y)});if(close)ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.setLineDash(dash);ctx.lineJoin='round';ctx.lineCap='round';ctx.stroke()}ctx.restore()}
function segment(a,b,color=colors.grid,width=1,dash=[]){poly([a,b],{stroke:color,width,dash})}
function curve(mu=current.mu,sigma=current.sigma,color=colors.green,width=3.2,dash=[]){let pts=[];for(let j=0;j<=420;j++){let x=45+j*310/420;pts.push(world(x,M.pdf(x,mu,sigma)*100))}poly(pts,{stroke:color,width,dash})}
function fill(a,b,color,alpha=.3){a=clamp(a,45,355);b=clamp(b,45,355);if(b<=a)return;let points=[world(a,0)];for(let i=0;i<=160;i++){let x=a+(b-a)*i/160;points.push(world(x,height(x)))}points.push(world(b,0));poly(points,{fill:color,close:true,alpha})}
function dot(p,color=colors.green,r=4.5){let a=project(p);ctx.save();ctx.shadowColor=color+'36';ctx.shadowBlur=12;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(a.x,a.y,r+2,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle=color;ctx.beginPath();ctx.arc(a.x,a.y,r,0,Math.PI*2);ctx.fill();ctx.restore()}
function text(label,p,{dx=0,dy=0,size=17,color=colors.ink,weight=500,align='center',back=false}={}){let a=project(p);ctx.save();const fs=size*(w<600?.82:1);ctx.font=`${weight} ${fs}px "PingFang SC","Microsoft YaHei",sans-serif`;ctx.textAlign=align;ctx.textBaseline='middle';if(back){let m=ctx.measureText(label),pad=7,ww=m.width+pad*2,hh=fs+12,x=a.x+dx-(align==='center'?ww/2:align==='right'?ww:pad);ctx.fillStyle='#f8fcf5ee';ctx.beginPath();ctx.roundRect(x,a.y+dy-hh/2,ww,hh,5);ctx.fill()}ctx.strokeStyle='#f5f8f2';ctx.lineWidth=4;ctx.lineJoin='round';ctx.strokeText(label,a.x+dx,a.y+dy);ctx.fillStyle=color;ctx.fillText(label,a.x+dx,a.y+dy);ctx.restore()}
function callout(label,anchor,{dx=0,dy=-35,size=17,color=colors.ink,align='center'}={}){let a=project(anchor);ctx.save();ctx.strokeStyle=color+'77';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(a.x+dx*.82,a.y+dy*.72);ctx.stroke();ctx.restore();text(label,anchor,{dx,dy,size,color,align,back:true})}
function bracket(a,b,y,label,color=colors.green){segment(world(a,y),world(b,y),color,1.4);segment(world(a,y-.055),world(a,y+.055),color,1.4);segment(world(b,y-.055),world(b,y+.055),color,1.4);text(label,world((a+b)/2,y),{dy:18,size:14,color})}
function arrow(a,b){let p=project(a),q=project(b),theta=Math.atan2(q.y-p.y,q.x-p.x);ctx.save();ctx.strokeStyle=colors.gold;ctx.fillStyle=colors.gold;ctx.lineWidth=1.7;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(q.x-8*Math.cos(theta-.5),q.y-8*Math.sin(theta-.5));ctx.lineTo(q.x-8*Math.cos(theta+.5),q.y-8*Math.sin(theta+.5));ctx.closePath();ctx.fill();ctx.restore()}
function base(){poly([world(45,0,-.7),world(355,0,-.7),world(355,0,.7),world(45,0,.7)],{fill:'#dfeadf',alpha:.33,close:true});for(let x=50;x<=350;x+=25)segment(world(x,0,-.7),world(x,0,.7),'#d1e0d0',.65);for(const z of[-.7,.7])segment(world(45,0,z),world(355,0,z),'#d3dfd1',.7);segment(world(45,0),world(355,0),'#809c80',1.2);for(let x=100;x<=300;x+=50){segment(world(x,0),world(x,-.055),'#78997a',1);text(number(x),world(x,-.15),{size:11,color:colors.muted})}text('观测值',world(355,0),{dx:11,size:12,align:'left',color:colors.muted});const axisHeight=Math.min(3.9,height(current.mu)*1.15);segment(world(60,0),world(60,axisHeight),'#b5c8b1',.8);text('密度',world(60,axisHeight),{dy:-12,size:12,color:colors.muted})}
function centerLine(label=true){let mu=current.mu;segment(world(mu,0),world(mu,height(mu)+.08),'#81a883',1.2,[4,5]);if(label)text(`μ = ${number(mu,0)}`,world(mu,-.36),{size:16,color:colors.green,back:true})}
function draw(now){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);if(!w||!h)return;if(state.step>=7){extension.draw({w,h,current,now});return}if(state.step>=4){sampling.draw({w,h,current,now});return}base();let mu=current.mu,sigma=current.sigma,peak=height(mu);
 if(state.step===0){fill(45,355,colors.green,.12);curve();text('钟形',world(mu,peak),{dy:-36,size:24});text(`N(${number(mu,0)}, ${number(sigma,0)}²)`,world(mu,peak*.48),{size:21,color:colors.green});callout('趋近 0',world(mu-3.1*sigma,height(mu-3.1*sigma)),{dx:-23,dy:-36,size:14,color:colors.muted});callout('趋近 0',world(mu+3.1*sigma,height(mu+3.1*sigma)),{dx:23,dy:-36,size:14,color:colors.muted});centerLine()}
 if(state.step===1){fill(45,mu,colors.blue,.25);fill(mu,355,colors.green,.24);curve();centerLine();text('对称轴',world(mu,peak),{dy:-34,size:19});text('50%',world(mu-.72*sigma,peak*.34),{size:22,color:colors.blue});text('50%',world(mu+.72*sigma,peak*.34),{size:22,color:colors.green})}
 if(state.step===2){fill(mu-sigma,mu+sigma,colors.blue,.17);curve();centerLine();for(const sign of[-1,1]){let x=mu+sign*sigma,y=height(x);segment(world(x,0),world(x,y),colors.blue,1,[3,4]);dot(world(x,y),colors.blue);callout(`拐点 ${number(x,0)}`,world(x,y),{dx:sign*(w<600?50:70),dy:-35,size:17,color:colors.blue})}bracket(mu-sigma,mu,-.58,'σ',colors.blue);bracket(mu,mu+sigma,-.58,'σ',colors.blue)}
 if(state.step===3){let z=state.area==='one'?1:1.959963984540054,lo=mu-z*sigma,hi=mu+z*sigma;if(state.area==='total'){fill(45,355,colors.green,.25);curve();text('总面积 = 1',world(mu,peak*.35),{size:26,color:colors.green});centerLine(false)}else{fill(lo,hi,colors.green,.23);fill(45,lo,colors.gold,.45);fill(hi,355,colors.gold,.45);curve();for(const x of[lo,hi]){segment(world(x,0),world(x,height(x)),colors.gold,1.2,[3,4]);dot(world(x,0),colors.gold,3.3);text(number(x,1),world(x,-.33),{size:15,color:colors.gold,back:true})}const p=M.probability(-z,z),tail=(1-p)/2;let pct=state.area==='one'?'68.27%':'95%';text(pct,world(mu,peak*.38),{size:29,color:colors.green});text('总面积 = 1',world(mu,peak),{dy:-32,size:19});for(const sign of[-1,1]){let x=mu+sign*(z+.43)*sigma;callout((tail*100).toFixed(state.area==='one'?2:1)+'%',world(x,height(x)),{dx:sign*(w<600?23:34),dy:-46,size:19,color:colors.gold})}text(state.area==='one'?'双尾 31.73%':'双尾合计 5%',world(mu,-.94),{size:17,color:colors.gold,back:true})}}
 if(now-stepStart<450)needDraw=true;
}
function updateLabels(){ $('mu').value=state.mu;$('sigma').value=state.sigma;$('mu-value').textContent=number(state.mu,0);$('sigma-value').textContent=number(state.sigma,0);$('stage-keyword').textContent=keywords[state.step];$('progress').textContent=`${state.step+1} / 9`;$('prev').disabled=state.step===0;$('next').disabled=state.step===8;$('probability-modes').hidden=state.step!==3;document.body.dataset.normalStep=state.step;extension?.update();sampling?.update();document.querySelectorAll('#steps button').forEach(b=>{let active=+b.dataset.step===state.step;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'step':'false')});document.querySelectorAll('[data-area]').forEach(b=>{let active=b.dataset.area===state.area;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});let description=descriptions[state.step];if(state.step===3&&state.area==='total')description='正态曲线下总面积为1。';if(state.step===3&&state.area==='one')description='均值加减一个标准差之间的概率约为68.27%，两侧尾部合计约31.73%。';if($('description').textContent!==description)$('description').textContent=description;const alt=`${description}当前均值${number(state.mu,0)}，标准差${number(state.sigma,0)}。可拖动旋转。`;if(canvas.getAttribute('aria-label')!==alt)canvas.setAttribute('aria-label',alt);needDraw=true}
function stop(){state.playing=false;$('play').textContent='▶';$('play').setAttribute('aria-label','自动演示');extension?.pause();sampling?.pause()}
function step(n,manual=true){if(manual)stop();state.step=clamp(n,0,8);if(state.step>=4){state.yaw=0;state.pitch=0;state.zoom=1}extension?.enter(state.step>=7?state.step:-1,!manual);sampling?.enter(state.step,!manual);stepStart=performance.now();autoStart=stepStart;updateLabels();document.querySelector('#steps button.active')?.scrollIntoView({block:'nearest',inline:'nearest'})}
function frame(now){const dt=Math.min(now-last,100);last=now;let moving=extension?.tick(dt)||false;moving=(sampling?.tick(dt)||false)||moving;if(state.playing){let t=(now-autoStart)/1000;if(state.step===5)state.n=[1,4,9,16,25,64][Math.min(5,Math.floor(t/1.3))];if(state.step===7)state.z=-2.5+5*Math.min(1,t/7);if(now-autoStart>(state.step===4?16000:8000)){if(state.step===8)stop();else{step(state.step+1,false)}}updateLabels();moving=true}const k=1-Math.exp(-dt/110);for(const key of['mu','sigma','yaw','pitch','zoom']){const diff=state[key]-current[key];if(Math.abs(diff)>.0001){current[key]+=diff*k;moving=true}else current[key]=state[key]}if(needDraw||moving){needDraw=false;draw(now)}requestAnimationFrame(frame)}
function front(){stop();state.yaw=0;state.pitch=0;state.zoom=1;needDraw=true}
function reset(){stop();Object.assign(state,{mu:200,sigma:20,yaw:state.step>=4?0:-.26,pitch:state.step>=4?0:.18,zoom:1,area:'ninetyfive',z:1,n:9});extension?.reset();sampling?.reset();updateLabels()}
extension=NormalExtension.create({canvas,ctx,state,manual:()=>{stop();needDraw=true},invalidate:()=>needDraw=true});
sampling=NormalSampling.create({canvas,ctx,state,manual:()=>{stop();needDraw=true},invalidate:()=>needDraw=true});
$('n').oninput=e=>{stop();state.n=Number(e.target.value);sampling.actions();updateLabels()};
$('z-bound').oninput=e=>{stop();state.z=Number(e.target.value);updateLabels()};
window.normalDiagnostics={get state(){return {...state}},get current(){return {...current}},get extension(){return extension.diagnostics},get sampling(){return sampling.diagnostics}};
document.querySelectorAll('#steps button').forEach(b=>b.onclick=()=>step(+b.dataset.step));$('prev').onclick=()=>step(state.step-1);$('next').onclick=()=>step(state.step+1);
for(const key of['mu','sigma'])$(key).addEventListener('input',e=>{stop();state[key]=Number(e.target.value);updateLabels()});document.querySelectorAll('[data-area]').forEach(b=>b.onclick=()=>{stop();state.area=b.dataset.area;updateLabels()});$('front').onclick=front;$('reset').onclick=reset;$('tilt').onclick=()=>{stop();if(Math.abs(state.yaw)+Math.abs(state.pitch)<.02){state.yaw=-.4;state.pitch=.3;needDraw=true}else front()};$('play').onclick=()=>{if(state.playing){stop();return}if(state.step===8)step(0);state.playing=true;extension.enter(state.step>=7?state.step:-1,true);sampling.enter(state.step,true);autoStart=performance.now();$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','暂停演示')};
canvas.addEventListener('pointerdown',e=>{stop();canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});canvas.classList.add('dragging');baseDrag={x:e.clientX,y:e.clientY,yaw:state.yaw,pitch:state.pitch,zoom:state.zoom,distance:pointers.size===2?distance():0}});
function distance(){const a=[...pointers.values()];return a.length<2?0:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)}
canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const d=distance();if(baseDrag.distance>0)state.zoom=clamp(baseDrag.zoom*d/baseDrag.distance,.65,1.75);else{baseDrag.distance=d;baseDrag.zoom=state.zoom}}else if(baseDrag){let dx=e.clientX-baseDrag.x,dy=e.clientY-baseDrag.y;state.yaw=clamp(baseDrag.yaw+dx*.006,-1.05,1.05);state.pitch=clamp(baseDrag.pitch+dy*.005,-.42,.65)}needDraw=true;e.preventDefault()});
function release(e){pointers.delete(e.pointerId);if(pointers.size===0){canvas.classList.remove('dragging');baseDrag=null}else{const a=[...pointers.values()][0];baseDrag={...a,yaw:state.yaw,pitch:state.pitch,zoom:state.zoom,distance:0}}}
canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);canvas.addEventListener('wheel',e=>{e.preventDefault();stop();state.zoom=clamp(state.zoom*Math.exp(-e.deltaY*.001),.65,1.75);needDraw=true},{passive:false});canvas.addEventListener('dblclick',front);
canvas.addEventListener('keydown',e=>{let handled=true;stop();if(e.key==='ArrowLeft')state.yaw=clamp(state.yaw-.12,-1.05,1.05);else if(e.key==='ArrowRight')state.yaw=clamp(state.yaw+.12,-1.05,1.05);else if(e.key==='ArrowUp')state.pitch=clamp(state.pitch-.1,-.42,.65);else if(e.key==='ArrowDown')state.pitch=clamp(state.pitch+.1,-.42,.65);else if(e.key==='+'||e.key==='=')state.zoom=clamp(state.zoom+.1,.65,1.75);else if(e.key==='-')state.zoom=clamp(state.zoom-.1,.65,1.75);else if(e.key==='0')front();else handled=false;if(handled){e.preventDefault();needDraw=true}});
document.addEventListener('keydown',e=>{if(e.target===canvas||e.target.tagName==='INPUT')return;if(e.key==='ArrowRight'){e.preventDefault();step(state.step+1)}else if(e.key==='ArrowLeft'){e.preventDefault();step(state.step-1)}});
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('fullscreen').textContent='F11 全屏'}};document.addEventListener('fullscreenchange',()=>$('fullscreen').textContent=document.fullscreenElement?'退出全屏':'全屏 ↗');resize();updateLabels();requestAnimationFrame(frame);
})();
